class Value:
 def __getattribute__(self,name): raise ValueError("never")
 def __bool__(self): raise ValueError("never")
def f(): pass
f.tag=Value()
print("tag" in dir(f))

def f(): pass
f.__dict__={7:9}
dir(f)

class Key:
 def __hash__(self): return hash("__new__")
 def __lt__(self,other): return True
 def __gt__(self,other): return False
 def __eq__(self,other): return False
def f(): pass
k=Key()
f.__dict__={k:7}
r=dir(f)
print(r[0] is k,len(r),len(f.__dict__))

