class Key:
 def __hash__(self): return hash("__new__")
 def __lt__(self,other): return True
 def __gt__(self,other): return False
 def __eq__(self,other):
  if "tag" in f.__dict__: del f.__dict__["tag"]
  return True
def f(): pass
k=Key()
f.__dict__={k:7,"tag":11}
r=dir(f)
names=[n for n in r if isinstance(n,str)]
